/**
 * Database schema for the curated seed (#4), the single source for migrations
 * (generated by drizzle-kit into `apps/api/migrations`) and for typed queries.
 *
 * The database holds the one committed seed: an import replaces every row in
 * one transaction. Value rules (ID format, https links, positive prices,
 * allowed kinds) are enforced by the importer's validation
 * (`src/seed/validate.ts`); the schema keeps keys, references and uniqueness.
 * `$type` narrows TypeScript types only.
 */
import type { RetailerId } from "@cartoptix/contracts";
import {
  boolean,
  foreignKey,
  index,
  integer,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";

export const retailers = pgTable("retailers", {
  retailerId: text("retailer_id").$type<RetailerId>().primaryKey(),
  name: text("name").notNull(),
  productUrlHosts: text("product_url_hosts").array().notNull(),
});

export const categories = pgTable("categories", {
  categoryId: text("category_id").primaryKey(),
  name: text("name").notNull(),
});

/** One rule per retailer; values are NULL when the rule is unverified, never zero. */
export const deliveryRules = pgTable("delivery_rules", {
  retailerId: text("retailer_id")
    .$type<RetailerId>()
    .primaryKey()
    .references(() => retailers.retailerId),
  status: text("status").$type<"verified" | "unverified">().notNull(),
  deliveryFeeCents: integer("delivery_fee_cents"),
  freeDeliveryFromCents: integer("free_delivery_from_cents"),
  minimumOrderCents: integer("minimum_order_cents"),
  thresholdIncludesMandatoryCharges: boolean("threshold_includes_mandatory_charges"),
  note: text("note"),
  sources: text("sources").array().notNull().default([]),
});

export const orderCharges = pgTable(
  "order_charges",
  {
    retailerId: text("retailer_id")
      .$type<RetailerId>()
      .notNull()
      .references(() => deliveryRules.retailerId),
    label: text("label").notNull(),
    amountCents: integer("amount_cents").notNull(),
    /** Spend at or above which the charge is waived; NULL if never waived. */
    waivedFromCents: integer("waived_from_cents"),
  },
  (table) => [primaryKey({ columns: [table.retailerId, table.label] })],
);

export const products = pgTable("products", {
  productId: text("product_id").primaryKey(),
  categoryId: text("category_id")
    .notNull()
    .references(() => categories.categoryId),
  representativeName: text("representative_name").notNull(),
  imageUrl: text("image_url"),
});

/** A published listing always carries its eligible offer. */
export const listings = pgTable(
  "listings",
  {
    listingId: text("listing_id").primaryKey(),
    productId: text("product_id").notNull(),
    retailerId: text("retailer_id").$type<RetailerId>().notNull(),
    /** Provenance back to the source export row. */
    sourceRecordId: text("source_record_id").notNull(),
    name: text("name").notNull(),
    specification: text("specification").notNull(),
    productUrl: text("product_url").notNull(),
    priceKind: text("price_kind").$type<"ordinary" | "unconditional_sale">().notNull(),
    unitPriceCents: integer("unit_price_cents").notNull(),
    excludedPromotions: text("excluded_promotions").array().notNull().default([]),
  },
  (table) => [
    // An exact product is listed at most once per retailer.
    unique("listings_product_retailer").on(table.productId, table.retailerId),
    foreignKey({ columns: [table.productId], foreignColumns: [products.productId] }),
    foreignKey({ columns: [table.retailerId], foreignColumns: [retailers.retailerId] }),
  ],
);

/**
 * Outbound clicks through to a retailer's product page (PR-07, #19).
 *
 * Deliberately outside the seed's replace-everything import. The importer
 * clears `listings` and `products` on every load, so a foreign key to either
 * would block a reimport or destroy the usage history the table was collected
 * to measure. The identifying columns are therefore recorded as values.
 *
 * Validation happens on the way in instead: the endpoint copies these columns
 * out of the matching listing row, so an unknown listing records nothing and a
 * caller cannot attribute a click to a retailer of its choosing.
 *
 * There is no user, session, device, address or agent column, and there must
 * not be one: this measures link use, not people. Rows here are usage records,
 * never buyers, conversions or billable clicks.
 */
export const clickEvents = pgTable(
  "click_events",
  {
    eventId: uuid("event_id").primaryKey().defaultRandom(),
    listingId: text("listing_id").notNull(),
    retailerId: text("retailer_id").$type<RetailerId>().notNull(),
    productId: text("product_id").notNull(),
    /** Recorded by the server's clock, never supplied by the client. */
    occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow(),
  },
  // Usage reporting (#22) reads events in time order.
  (table) => [index("click_events_occurred_at").on(table.occurredAt)],
);
